-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("What is it you want, " .. e.other:GetRaceName() .. "?  I have no time to speak with your kind.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 25266 }) then
    e.self:Say("Thank you for bringing the supplies, " .. e.other:GetCleanName() .. ". This season has not treated my clan well.  The winds have grown colder and the Coldain are now brazen enough to hunt the same animals we do.  Take this torque back to Svekk and he will repay you for the supplies.")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(406, -30, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:SummonItem(25278)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
